"""A bounded chat/tool loop with actual Ollama and explicit offline providers.

This baseline deliberately has no OpenTelemetry or GenAI instrumentation.
"""
import json
import os
import re
import time
import uuid

import httpx

from tools import SERVICES, TOOL_DEFINITIONS, execute_tool

SYSTEM_PROMPT = """You are Incident Desk, a local troubleshooting practice assistant.
All service data and documents are synthetic demo fixtures, not live production data.
Use tools to investigate service health, slow requests, deployments and incidents.
Use search_docs for troubleshooting guidance. You can make multiple tool calls.
Base conclusions on returned evidence. Explain failed tools and missing evidence.
Do not claim to fix or deploy anything. Keep replies concise and do not reveal hidden reasoning."""


def offline_response(messages):
    user_index = max(i for i, m in enumerate(messages) if m["role"] == "user")
    prompt = messages[user_index]["content"]
    prior = " ".join(m.get("content", "") for m in messages[:user_index] if m["role"] == "user")
    service = next((s for s in SERVICES if s in prompt.lower()), None)
    service = service or next((s for s in SERVICES if s in prior.lower()), "checkout")
    if messages[-1]["role"] == "user":
        incident = re.search(r"INC-\d+", prompt, re.I)
        if incident:
            calls = [("lookup_incident", {"incident_id": incident.group().upper()})]
        elif len([s for s in SERVICES if s in prompt.lower()]) > 1:
            selected = [s for s in SERVICES if s in prompt.lower()]
            calls = [("get_service_health", {"service": s}) for s in selected]
            calls += [("search_docs", {"query": prompt})]
            calls += [("list_deployments", {"service": s}) for s in selected]
        elif any(word in prompt.lower() for word in ("slow", "health", "deploy", "checkout", "payments", "inventory", "changed", "error", "latency")):
            calls = [("get_service_health", {"service": service}), ("search_docs", {"query": service + " " + prompt}), ("list_deployments", {"service": service})]
        else:
            return {"role": "assistant", "content": "Ask me to investigate checkout, payments or inventory. For example: Why is checkout slow?"}
        return {"role": "assistant", "content": "", "tool_calls": [
            {"function": {"name": name, "arguments": args}} for name, args in calls]}
    results = [json.loads(m["content"]) for m in messages[user_index + 1:] if m["role"] == "tool"]
    if any(isinstance(r, dict) and "error" in r for r in results):
        text = "The tool dependency failed, so I cannot verify the service state. Disable the failure scenario and retry."
    elif results and results[0] is None:
        text = "That incident was not found. The tool returned null; no incident details are available."
    elif len([r for r in results if isinstance(r, dict) and "p95_latency_ms" in r]) > 1:
        health_rows = [r for r in results if isinstance(r, dict) and "p95_latency_ms" in r]
        text = "\n".join(f"{r['service'].capitalize()}: {r['status']}, p95 {r['p95_latency_ms']} ms, errors {r['error_rate_percent']}%." for r in health_rows)
        text += "\nInvestigate the degraded service first; the remaining services are healthy in these synthetic fixtures." if any(r["status"] != "healthy" for r in health_rows) else "\nThese services are healthy in the synthetic fixtures. No service degradation is present in this evidence."
    elif results and isinstance(results[0], dict) and "p95_latency_ms" in results[0]:
        health = results[0]
        text = f"{service.capitalize()} is {health['status']} in the demo fixture: p95 latency {health['p95_latency_ms']} ms, errors {health['error_rate_percent']}%, database pool usage {health['database_pool_usage_percent']}%."
        if health["status"] == "degraded":
            text += " The checkout-2.8.0 deployment and its new synchronous inventory query are worth investigating. Compare query duration and connection lifetime before deciding on a rollback."
    else:
        text = "Incident evidence: " + json.dumps(results[0])
    return {"role": "assistant", "content": text}


async def call_model(messages, provider, model, scenario):
    if scenario == "model_failure":
        raise RuntimeError("Simulated model provider failure")
    if provider == "demo":
        return {"message": offline_response(messages), "model": "offline-rule-engine", "done_reason": "stop"}
    base_url = os.getenv("OLLAMA_BASE_URL", "http://127.0.0.1:11434").rstrip("/")
    async with httpx.AsyncClient(timeout=120) as client:
        response = await client.post(base_url + "/api/chat", json={
            "model": model, "messages": messages, "tools": TOOL_DEFINITIONS,
            "stream": False, "think": False, "keep_alive": "10m",
            "options": {"temperature": 0.2, "num_predict": 512, "num_ctx": 8192},
        })
        response.raise_for_status()
        return response.json()


async def run_agent(prompt, history, provider, model, scenario="normal"):
    if scenario == "context_limit" or len(prompt) > 4000:
        raise ValueError("Demo context limit exceeded; use a shorter message")
    messages = [{"role": "system", "content": SYSTEM_PROMPT}, *history, {"role": "user", "content": prompt}]
    calls = []
    started = time.perf_counter()
    tool_count = 0
    for step in range(6):
        yield {"event": "model.start", "data": {"step": step + 1, "provider": provider, "model": model if provider == "ollama" else "offline-rule-engine"}}
        response = await call_model(messages, provider, model, scenario)
        message = response.get("message")
        if not isinstance(message, dict) or message.get("role") != "assistant":
            raise ValueError("Provider returned an invalid assistant message")
        # Keep user-visible content and tool protocol; hidden reasoning is not stored.
        message = {k: v for k, v in message.items() if k in ("role", "content", "tool_calls")}
        messages.append(message)
        call_usage = {"model": response.get("model", model), "input_tokens": response.get("prompt_eval_count"),
                      "output_tokens": response.get("eval_count"), "finish_reason": response.get("done_reason")}
        calls.append(call_usage)
        yield {"event": "model.end", "data": call_usage}
        tool_calls = message.get("tool_calls") or []
        if not tool_calls:
            answer = message.get("content", "")
            if not answer:
                raise ValueError("Provider returned no answer")
            yield {"event": "message", "data": {"text": answer}}
            def total(field):
                return sum(c[field] for c in calls) if all(isinstance(c[field], int) for c in calls) else None
            yield {"event": "done", "data": {"provider": provider, "model": call_usage["model"],
                "model_calls": len(calls), "tool_calls": tool_count, "input_tokens": total("input_tokens"),
                "output_tokens": total("output_tokens"), "duration_ms": round((time.perf_counter() - started) * 1000),
                "messages": messages[1:]}}
            return
        if not isinstance(tool_calls, list) or len(tool_calls) > 8:
            raise ValueError("Provider returned invalid or excessive tool calls")
        for call in tool_calls:
            function = call.get("function", {})
            name = function.get("name")
            args = function.get("arguments", {})
            if isinstance(args, str):
                args = json.loads(args)
            if not isinstance(name, str) or not isinstance(args, dict):
                raise ValueError("Provider returned invalid tool arguments")
            call_id = call.get("id") or "demo-call-" + uuid.uuid4().hex
            tool_count += 1
            yield {"event": "tool.start", "data": {"id": call_id, "name": name, "arguments": args}}
            try:
                result = await execute_tool(name, args, scenario)
                feedback = result
                event = {"id": call_id, "name": name, "result_produced": True, "result": result}
            except (ValueError, RuntimeError) as exc:
                feedback = {"error": type(exc).__name__, "message": str(exc)}
                event = {"id": call_id, "name": name, "result_produced": False, **feedback}
            yield {"event": "tool.end", "data": event}
            messages.append({"role": "tool", "tool_name": name, "content": json.dumps(feedback)})
    raise RuntimeError("Agent reached its six-request limit without a final answer")

"""Read-only tools backed by synthetic local service fixtures."""
import asyncio
import json
import re
from pathlib import Path

ROOT = Path(__file__).parent
SERVICES = json.loads((ROOT / "data/services.json").read_text())
DOCUMENTS = json.loads((ROOT / "data/docs.json").read_text())


def definition(name, description, argument, description_arg):
    return {"type": "function", "function": {"name": name, "description": description,
        "parameters": {"type": "object", "properties": {argument: {"type": "string", "description": description_arg}},
                       "required": [argument], "additionalProperties": False}}}


TOOL_DEFINITIONS = [
    definition("get_service_health", "Read a synthetic service's health, latency and errors.", "service", "checkout, payments or inventory"),
    definition("search_docs", "Search local troubleshooting documents and release notes.", "query", "Troubleshooting question or keywords"),
    definition("list_deployments", "Read recent synthetic deployments for a service.", "service", "checkout, payments or inventory"),
    definition("lookup_incident", "Read a synthetic incident. Returns null when it does not exist.", "incident_id", "INC-100 or another incident ID"),
]


async def retrieve_documents(query: str):
    terms = set(re.findall(r"[a-z0-9]+", query.lower())) - {"the", "is", "why", "what", "and", "for", "a", "to"}
    scored = [(len(terms & set(re.findall(r"[a-z0-9]+", (d["title"] + " " + d["text"]).lower()))), d)
              for d in DOCUMENTS]
    return [d for score, d in sorted(scored, key=lambda item: item[0], reverse=True) if score > 0][:3]


async def execute_tool(name: str, arguments: dict, scenario: str = "normal"):
    spec = next((t["function"] for t in TOOL_DEFINITIONS if t["function"]["name"] == name), None)
    if spec is None:
        raise ValueError("Unknown tool")
    required = spec["parameters"]["required"]
    if set(arguments) != set(required) or any(not isinstance(arguments[k], str) for k in required):
        raise ValueError("Tool arguments must match the declared string parameters")
    await asyncio.sleep(0.04)
    if scenario == "tool_failure":
        raise RuntimeError("Simulated tool dependency failure")
    if name == "search_docs":
        return {"query": arguments["query"], "documents": await retrieve_documents(arguments["query"]), "source": "demo-fixture"}
    if name == "lookup_incident":
        return {"id": "INC-100", "service": "checkout", "status": "investigating"} if arguments["incident_id"] == "INC-100" else None
    service = arguments["service"].lower()
    if service not in SERVICES:
        raise ValueError("Unknown service; choose checkout, payments or inventory")
    if name == "get_service_health":
        return {"service": service, **SERVICES[service], "source": "demo-fixture"}
    return {"service": service, "deployments": [{"release": SERVICES[service]["release"], "time": "09:40", "source": "demo-fixture"}]}

